#!/bin/bash
# Raw runs for the "same issue, several fixes" variants (generated by our own coding agents for this benchmark).
# usage: runs.sh <variant id e.g. 2283-v1> <targeted filter> [runtime]
# Head:  /data/src/mp-var-<id> at branch cs-var/<id>; build + targeted + full SourceGenerator suite -> $WORK/out/var-<id>
# FWF:   /data/src/mp-var-<id>-fwf = head with every changed non-test source file under src/ reverted to base 32258fdb,
#        tests kept -> $WORK/out/var-<id>-fwf (skipped when the change touches no file under src/)
# runtime: also build + run tests/MessagePack.Tests -f net8.0 on head -> $WORK/out/rt-var-<id>
# Same scripts as the agent branches: evidence/scripts/run.sh (SDK 8.0.402, -m:8, MaxCpuCount=8).
set -u
export WORK=${WORK:-/data/work/var}
HERE=$(cd "$(dirname "$0")" && pwd)
id=$1; filt=$2; rt=${3:-}
BASE=32258fdbee4bcd653c79f51b4376b5103c6f4d27
SG=tests/MessagePack.SourceGenerator.Tests/MessagePack.SourceGenerator.Tests.csproj
wt=/data/src/mp-var-$id
mkdir -p $WORK/out; [ -e $WORK/out/base ] || ln -s /data/work/out/base $WORK/out/base
bash $HERE/../scripts/run.sh var-$id $wt $SG "$SG=$filt" yes
src=$(command git -C $wt diff --name-only $BASE HEAD -- src/)
if [ -n "$src" ]; then
  f=$wt-fwf
  [ -d $f ] || command git -C /data/src/mp worktree add --detach $f HEAD >/dev/null 2>&1
  command git -C $f checkout -q --detach -f $(command git -C $wt rev-parse HEAD)
  command git -C $f checkout $BASE -- $src
  bash $HERE/../scripts/run.sh var-$id-fwf $f $SG "$SG=$filt" yes
fi
if [ "$rt" = runtime ]; then
  . /data/work/env.sh
  L=$WORK/out/rt-var-$id; mkdir -p $L; cd $wt
  P=tests/MessagePack.Tests/MessagePack.Tests.csproj
  echo "label=rt-var-$id wt=$wt head=$(command git rev-parse HEAD)" > $L/meta.txt
  s=$(date +%s); dotnet build $P -f net8.0 -m:8 -c Debug -v:m -clp:Summary > $L/build.log 2>&1; rc=$?
  echo "build_rc=$rc build_s=$(( $(date +%s)-s ))" >> $L/meta.txt
  if [ $rc -eq 0 ]; then
    s=$(date +%s); timeout 1800 dotnet test $P -f net8.0 --no-build -c Debug --logger "trx;LogFileName=$L/full.trx" -- RunConfiguration.MaxCpuCount=8 > $L/full.log 2>&1
    echo "full_rc=$? full_s=$(( $(date +%s)-s ))" >> $L/meta.txt
  fi
  echo DONE >> $L/meta.txt
fi
